  "claims": [
    {
      "claim": "Cicaprost, a prostanoid with an OCH2COOH ether-acetic-acid side chain, had a mean oral AUC0-∞ of 422 pg·h/ml after 7.6 µg versus an IV infusion AUC0-∞ of 409 pg·h/ml after 2.1 µg, corresponding to 100% oral bioavailability; this is direct oral-vs-IV exposure evidence that an ionized acidic prostanoid can exceed the 20% threshold.",
      "card_ids": ["C104", "C84"]
    },
    {
      "claim": "Other L3 oral exposure records for prostanoid analogs (beraprost, BPS-314d, iloprost, nocloprost, limaprost, arbaprostil, selexipag metabolite) show measurable oral Cmax at microgram doses but do not report F; they are neutral for the F≥20% threshold.",
      "card_ids": ["C118", "C109", "C80", "C117", "C108", "C87", "C75", "C110", "C96", "C69", "C78", "C100", "C93", "C73", "C82", "C83", "C103", "C81", "C101", "C114", "C92", "C99", "C71", "C102", "C98", "C112", "C95", "C79", "C105", "C115", "C76", "C88", "C91", "C97"]
    },
    {
      "claim": "No L3 record affirmatively supports F<20% for the query or a close analog; unrelated chemotypes (nadolol, simvastatin acid, pravastatin, indinavir, dexloxiglumide, brivaracetam) only report Cmax/AUC without threshold-relevant F.",
      "card_ids": ["C107", "C85", "C106", "C89", "C94", "C111", "C90", "C86", "C116", "C77", "C113", "C74", "C70", "C72"]
    },
    {
      "claim": "Prior human L1/L2 evidence remains supportive: FK788 (aryloxyacetic acid on a fused bicyclic ring) 55%, etodolac (ionizable carboxylic acid) 80-100%, fed-state KNI-272 capsule 36.4%, and food increased propranolol F from 0.27 to 0.46.",
      "card_ids": ["C10", "C17", "C20", "C05", "C41", "C09", "C50", "C67"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C104", "C84", "C118"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "No fed-state pharmacokinetic study is available for the query; the cicaprost F=100% record does not specify prandial state.",
    "Cicaprost differs from the query in the attachment of the OCH2COOH side chain (exocyclic methylene vs aryl ether) and in the omega chain; transporter/efflux differences are unknown.",
    "Most L3 prostanoid records report Cmax/AUC without F, so they cannot directly establish the threshold.",
    "No experimental permeability or solubility data are available for the query; the logD-based prior is indirect.",
    "Sub-20% L2 values come from non-human species or alternative formulations (cherry syrup), limiting their transferability to a human oral solid-dose fed-state prediction."
  ],
  "decision_summary": "Predicted high (F≥20%) because direct human L1/L2 evidence (FK788 55%, etodolac 80-100%, fed-state KNI-272 36.4%) is reinforced by L3 oral exposure evidence: cicaprost, a prostanoid with an OCH2COOH side chain, had 100% oral bioavailability by oral-vs-IV AUC. No L3 record affirmatively supports F<20%; sub-20% records are non-human or formulation-specific. Confidence strengthened to high."
}

